  const response = await apiClient.get(`/users/${id}`)
  return response.data
}

// any 금지 -> unknown 사용
const parseJSON = (data: string): unknown => {
  return JSON.parse(data)
}

// function 키워드 금지
// function badFunction() {} -> const 화살표 함수 사용
```

