## 잘못된 순서 (금지)

```typescript
export const useBadHook = () => {
  const queryClient = useQueryClient()  // Global Hook 먼저 - 잘못됨
  useEffect(() => { /* ... */ }, [])    // 중간에 useEffect - 잘못됨
  const [state, setState] = useState()  // State가 나중에 - 잘못됨
  const { data } = useQuery({})         // Effect 뒤에 Query - 잘못됨
}
```

